```

### Main — Putting It All Together

```xiom
fn main() -> Int {
  use plugin_manager;
  let mut pm = plugin_manager.create[UpperCasePlugin]();
  pm.register(UpperCasePlugin{});
  let names = pm.list_plugins();
  io.println(names);
  return 0;
}
